"use strict";
import { motion } from "framer-motion";
import { useState } from "react";
import styled from "styled-components";
import { colors } from "theme/colors";
import { Flex, Text, styled as uiStyled } from "ui/src";
const ToggleContainer = uiStyled(Flex, {
  flexDirection: "row",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: 2,
  gap: 2,
  position: "relative"
});
const ToggleButton = uiStyled(Flex, {
  paddingHorizontal: "$spacing12",
  paddingVertical: "$spacing4",
  borderRadius: "$roundedFull",
  cursor: "pointer",
  justifyContent: "center",
  alignItems: "center",
  position: "relative",
  zIndex: 1
});
const ActiveBackground = styled(motion.div)`
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  background-color: ${colors.surface2_dark};
  border-radius: 9999px;
  z-index: 0;
`;
export default function CurrencyToggle({ labels = ["ABX", "USDC"] }) {
  const [currency, setCurrency] = useState(labels[0]);
  return <ToggleContainer>
      {labels.map((label) => {
    const isActive = currency === label;
    return <ToggleButton key={label} onPress={() => setCurrency(label)}>
            {isActive && <ActiveBackground
      layoutId="activeCurrencyToggle"
      transition={{
        type: "spring",
        stiffness: 500,
        damping: 30
      }}
    />}
            <Text variant="buttonLabel4" color={isActive ? "$neutral1" : "$neutral2"} zIndex={2}>
              {label}
            </Text>
          </ToggleButton>;
  })}
    </ToggleContainer>;
}
